import type { NextConfig } from "next";

// Baseline security headers applied to every route. Each is paranoid
// in a different direction:
//
// - X-Content-Type-Options: nosniff — block the browser from guessing
//   a different MIME than what we sent. Mostly protects against the
//   "looks like HTML to a sniffer, actually JS to the loader" class
//   of XSS via uploaded files; harmless here since the site has no
//   uploads, but cheap insurance.
// - Referrer-Policy: strict-origin-when-cross-origin — leak only the
//   origin (not the full URL) when a reader clicks an outbound link,
//   so /search?search=<their-query> doesn't show up in third-party
//   analytics. Same default Chromium ships with — explicit is better.
// - X-Frame-Options: SAMEORIGIN — refuse to be iframed anywhere but
//   our own origin. Prevents clickjacking attacks that overlay the
//   site under a different page.
// - Permissions-Policy: camera=(), microphone=(), geolocation=(),
//   interest-cohort=() — the site doesn't use any of these APIs;
//   denying them removes a class of fingerprinting / abuse surface.
//   `interest-cohort=()` opts the site out of FLoC even though that
//   particular experiment is dead — it costs nothing and is a clear
//   signal to similar future schemes.
//
// Added by the security audit:
// - Strict-Transport-Security (audit C-03) — tells the browser to
//   refuse any future HTTP load of this origin for two years. The
//   `preload` directive opts us into the hardcoded HSTS list shipped
//   with Chromium / Firefox — once submitted at hstspreload.org,
//   even a first-ever visit is HTTPS-only. Production-only because
//   on http://localhost the browser ignores HSTS anyway, but on the
//   occasional https://localhost dev box the header would pin
//   future loads of the dev server too.
// - Cross-Origin-Opener-Policy: same-origin (audit M-02) — strips
//   window.opener references from any cross-origin window we open
//   or that opens us. Also disables `window.open(..., 'noopener')`
//   targeted tab-napping.
// - Cross-Origin-Resource-Policy: same-origin (audit M-02) — blocks
//   other origins from embedding our resources via <img>, <script>,
//   <iframe>, etc.
//
// COEP (Cross-Origin-Embedder-Policy: require-corp) is now safe to
// turn on — the subresource survey shows the site loads everything
// from the same origin: brand fonts are local .ttf files imported
// from app/fonts/, Tailwind is bundled, no Google Fonts CDN, no
// third-party scripts. With every subresource same-origin and
// CORP=same-origin (from the rule above) already set, COEP can
// require CORP on cross-origin loads without breaking anything.
//
// CSP is set per-request by `proxy.ts` (Next.js 16's renamed-from-
// middleware file) so it can include a fresh nonce that lets the
// inline JSON-LD scripts through without `'unsafe-inline'`. See the
// proxy file for the actual directives. We intentionally do NOT
// emit CSP from this static header set — a static + dynamic CSP
// would result in two headers and unpredictable browser behavior.
const isProd = process.env.NODE_ENV === "production";

const SECURITY_HEADERS = [
  { key: "X-Content-Type-Options", value: "nosniff" },
  { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
  { key: "X-Frame-Options", value: "SAMEORIGIN" },
  {
    key: "Permissions-Policy",
    value: "camera=(), microphone=(), geolocation=(), interest-cohort=()",
  },
  { key: "Cross-Origin-Opener-Policy", value: "same-origin" },
  { key: "Cross-Origin-Resource-Policy", value: "same-origin" },
  { key: "Cross-Origin-Embedder-Policy", value: "require-corp" },
  // Only attach HSTS in production builds — see the note above.
  ...(isProd
    ? [
        {
          key: "Strict-Transport-Security",
          value: "max-age=63072000; includeSubDomains; preload",
        },
      ]
    : []),
];

const nextConfig: NextConfig = {
  // Drop the `X-Powered-By: Next.js` header. Combined with the
  // backend's H-05 fix (disabling Express's matching header), this
  // closes the cheapest stack-fingerprinting probe. Audit H-05.
  poweredByHeader: false,

  // ── Cache headers ────────────────────────────────────────────────
  // Public pages are fine with the default cache behavior — they're
  // statically rendered and revalidated, and a stale homepage
  // briefly is harmless.
  //
  // The CMS is different. Every rebuild emits new hashed chunk
  // filenames; if a browser hangs onto cached admin HTML from before
  // the rebuild, the page tries to load chunks that no longer exist
  // on disk and breaks blank. So we explicitly opt every /admin/*
  // HTML response out of caching. The hashed JS / CSS chunks under
  // /_next/static/ stay `immutable` (filenames change when content
  // changes, so they're always safe to cache forever).
  async headers() {
    return [
      // Security headers — applied to every route. Keep this rule
      // first; subsequent rules with overlapping `source` will add to
      // (not replace) these headers.
      {
        source: "/:path*",
        headers: SECURITY_HEADERS,
      },
      {
        source: "/admin/:path*",
        headers: [
          {
            key: "Cache-Control",
            value: "no-store, no-cache, must-revalidate, max-age=0",
          },
          { key: "Pragma", value: "no-cache" },
          { key: "Expires", value: "0" },
        ],
      },
    ];
  },
};

export default nextConfig;
