// Runtime schemas for public API response shapes.
//
// `types/index.ts` is the authoritative TypeScript surface — these
// schemas mirror it for runtime validation. Each schema is annotated
// with `z.ZodType<T>` so a missing/typo'd field shows up as a
// compile error here rather than silently passing every test.
//
// Wired into the request() helper in `lib/api.ts` — see the
// safeParse + warn + fallback pattern there. We do NOT throw on a
// schema mismatch; existing behavior is preserved (cast through),
// but the mismatch is logged for observability. Promote to throw
// later if we want stricter handling.

import { z } from "zod";
import type {
  ChapterCard,
  FullChapter,
  FullStory,
  HomepageCard,
  PageMeta,
  Paginated,
  SeriesCard,
  SeriesDetail,
  SeriesStatus,
  StoryCard,
  Tag,
} from "@/types";

export const TagSchema: z.ZodType<Tag> = z.object({
  id: z.string(),
  name: z.string(),
  slug: z.string(),
  isAdult: z.boolean(),
  createdAt: z.string(),
});

export const SeriesStatusSchema: z.ZodType<SeriesStatus> = z.enum([
  "ONGOING",
  "COMPLETE",
  "HIATUS",
]);

export const StoryCardSchema: z.ZodType<StoryCard> = z.object({
  type: z.literal("story").optional(),
  id: z.string(),
  title: z.string(),
  excerpt: z.string(),
  estimatedReadMinutes: z.number(),
  likeCount: z.number(),
  accumulatedReadSeconds: z.number(),
  isAuthorsChoice: z.boolean(),
  isAdult: z.boolean(),
  publishedAt: z.string().nullable(),
  tags: z.array(TagSchema),
});

export const ChapterCardSchema: z.ZodType<ChapterCard> = z.object({
  type: z.literal("chapter").optional(),
  id: z.string(),
  title: z.string(),
  excerpt: z.string(),
  orderIndex: z.number(),
  estimatedReadMinutes: z.number(),
  likeCount: z.number(),
  accumulatedReadSeconds: z.number(),
  isAuthorsChoice: z.boolean(),
  isAdult: z.boolean(),
  publishedAt: z.string().nullable(),
  series: z.object({ id: z.string(), title: z.string() }),
  tags: z.array(TagSchema),
});

export const SeriesCardSchema: z.ZodType<SeriesCard> = z.object({
  id: z.string(),
  title: z.string(),
  excerpt: z.string(),
  status: SeriesStatusSchema,
  likeCount: z.number(),
  accumulatedReadSeconds: z.number(),
  isAdult: z.boolean(),
  createdAt: z.string(),
  tags: z.array(TagSchema),
  chapters: z.array(
    z.object({
      id: z.string(),
      title: z.string(),
      orderIndex: z.number(),
      publishedAt: z.string().nullable(),
    }),
  ),
  _count: z.object({ chapters: z.number() }).optional(),
});

// `HomepageCard` is a discriminated union by `type`. The base
// StoryCard/ChapterCard schemas leave `type` optional (since the
// non-homepage endpoints don't ship it), so we inline the homepage
// variants here with `type` required — discriminatedUnion needs a
// concrete discriminator value on each arm.
const HomepageStoryCardSchema = z.object({
  type: z.literal("story"),
  id: z.string(),
  title: z.string(),
  excerpt: z.string(),
  estimatedReadMinutes: z.number(),
  likeCount: z.number(),
  accumulatedReadSeconds: z.number(),
  isAuthorsChoice: z.boolean(),
  isAdult: z.boolean(),
  publishedAt: z.string().nullable(),
  tags: z.array(TagSchema),
});

const HomepageChapterCardSchema = z.object({
  type: z.literal("chapter"),
  id: z.string(),
  title: z.string(),
  excerpt: z.string(),
  orderIndex: z.number(),
  estimatedReadMinutes: z.number(),
  likeCount: z.number(),
  accumulatedReadSeconds: z.number(),
  isAuthorsChoice: z.boolean(),
  isAdult: z.boolean(),
  publishedAt: z.string().nullable(),
  series: z.object({ id: z.string(), title: z.string() }),
  tags: z.array(TagSchema),
});

export const HomepageCardSchema: z.ZodType<HomepageCard> =
  z.discriminatedUnion("type", [
    HomepageStoryCardSchema,
    HomepageChapterCardSchema,
  ]);

export const FullStorySchema: z.ZodType<FullStory> = z.object({
  id: z.string(),
  title: z.string(),
  excerpt: z.string(),
  estimatedReadMinutes: z.number(),
  likeCount: z.number(),
  isAuthorsChoice: z.boolean(),
  isAdult: z.boolean(),
  authorsNote: z.string().nullable(),
  epigraph: z.string().nullable(),
  publishedAt: z.string(),
  tags: z.array(TagSchema),
  content: z.string(),
  page: z.number(),
  totalPages: z.number(),
});

export const FullChapterSchema: z.ZodType<FullChapter> = z.object({
  id: z.string(),
  title: z.string(),
  excerpt: z.string(),
  orderIndex: z.number(),
  estimatedReadMinutes: z.number(),
  likeCount: z.number(),
  isAuthorsChoice: z.boolean(),
  isAdult: z.boolean(),
  authorsNote: z.string().nullable(),
  epigraph: z.string().nullable(),
  publishedAt: z.string(),
  series: z.object({ id: z.string(), title: z.string() }),
  tags: z.array(TagSchema),
  content: z.string(),
  page: z.number(),
  totalPages: z.number(),
  prev: z
    .object({
      id: z.string(),
      title: z.string(),
      orderIndex: z.number(),
    })
    .nullable(),
  next: z
    .object({
      id: z.string(),
      title: z.string(),
      orderIndex: z.number(),
    })
    .nullable(),
});

export const SeriesDetailSchema: z.ZodType<SeriesDetail> = z.object({
  id: z.string(),
  title: z.string(),
  excerpt: z.string(),
  authorsNote: z.string().nullable(),
  status: SeriesStatusSchema,
  likeCount: z.number(),
  accumulatedReadSeconds: z.number(),
  createdAt: z.string(),
  tags: z.array(TagSchema),
  chapters: z.array(
    z.object({
      id: z.string(),
      title: z.string(),
      excerpt: z.string(),
      orderIndex: z.number(),
      estimatedReadMinutes: z.number(),
      likeCount: z.number(),
      publishedAt: z.string(),
      tags: z.array(TagSchema),
    }),
  ),
});

export const PageMetaSchema: z.ZodType<PageMeta> = z.object({
  total: z.number(),
  page: z.number(),
  limit: z.number(),
  totalPages: z.number(),
});

// `Paginated<T>` is generic; export a builder rather than a single
// schema so each list endpoint can pin to its own item type.
export function paginatedSchema<T extends z.ZodTypeAny>(
  item: T,
): z.ZodType<Paginated<z.infer<T>>> {
  return z.object({
    data: z.array(item),
    meta: PageMetaSchema,
  }) as z.ZodType<Paginated<z.infer<T>>>;
}

// Tiny constant-shape schemas used by the like endpoints — no type
// alias in types/index.ts, defined inline here.
export const LikeStatusSchema = z.object({ liked: z.boolean() });
export const LikeMutationSuccessSchema = z.object({ liked: z.boolean() });

// ============================================================
// Public API client. Server-component friendly — never reads
// localStorage or other client globals. Caching is opt-in per
// call: homepage requests revalidate every 2 minutes, reading
// pages opt out of cache entirely.
// ============================================================

import { z } from "zod";
import {
  FullChapterSchema,
  FullStorySchema,
  HomepageCardSchema,
  LikeMutationSuccessSchema,
  LikeStatusSchema,
  paginatedSchema,
  SeriesCardSchema,
  SeriesDetailSchema,
  StoryCardSchema,
  TagSchema,
} from "@/lib/schemas";
import type {
  FullChapter,
  FullStory,
  HomepageCard,
  Paginated,
  SeriesCard,
  SeriesDetail,
  StoryCard,
  Tag,
} from "@/types";

const API_URL =
  process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:3001/api";

const HOMEPAGE_REVALIDATE: RequestInit["next"] = { revalidate: 120 };
const READING_NO_STORE: RequestInit["cache"] = "no-store";

class ApiError extends Error {
  constructor(
    message: string,
    public status: number,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

/**
 * Fetch + JSON parse + optional runtime shape check.
 *
 * If `schema` is passed, the response is run through `safeParse`. On
 * mismatch we log to console and *fall through to the cast* — the
 * existing behavior is preserved, but a future audit of console logs
 * will surface schema drift between backend and frontend (the audit's
 * C07 concern). Promote to `parse()` later if we want stricter
 * handling. Callers that omit `schema` behave exactly as before.
 */
async function request<T>(
  path: string,
  init?: RequestInit,
  schema?: z.ZodType<T>,
): Promise<T> {
  const res = await fetch(`${API_URL}${path}`, init);
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new ApiError(
      `GET ${path} -> ${res.status}${text ? `: ${text}` : ""}`,
      res.status,
    );
  }
  const data: unknown = await res.json();
  if (schema) {
    const result = schema.safeParse(data);
    if (result.success) return result.data;
    if (typeof console !== "undefined") {
      console.warn(
        `[API] Schema mismatch for ${path}:`,
        result.error.issues,
      );
    }
    // Fall through — preserve pre-validation behavior on drift.
  }
  return data as T;
}

// ── Tags ─────────────────────────────────────────────────────────

// Schemas come from `lib/schemas.ts`; `z.array(TagSchema)` etc are
// `z.ZodType<Tag[]>` so the request<T> generic stays inferred.

export function getTags() {
  return request<Tag[]>(
    "/tags",
    { next: HOMEPAGE_REVALIDATE },
    z.array(TagSchema),
  );
}

export function getTagBySlug(slug: string) {
  return request<Tag>(
    `/tags/by-slug/${encodeURIComponent(slug)}`,
    { next: HOMEPAGE_REVALIDATE },
    TagSchema,
  );
}

// ── Stories ──────────────────────────────────────────────────────

export interface StoryListQuery {
  search?: string;
  tagIds?: string[];
  page?: number;
  limit?: number;
}

export function getStories(query: StoryListQuery = {}) {
  const params = new URLSearchParams();
  if (query.search) params.set("search", query.search);
  if (query.tagIds) for (const id of query.tagIds) params.append("tagIds", id);
  if (query.page) params.set("page", String(query.page));
  if (query.limit) params.set("limit", String(query.limit));
  const qs = params.toString() ? `?${params}` : "";
  return request<Paginated<StoryCard>>(
    `/stories${qs}`,
    { cache: READING_NO_STORE },
    paginatedSchema(StoryCardSchema),
  );
}

export function getStory(id: string, page = 1) {
  return request<FullStory>(
    `/stories/${id}?page=${page}`,
    { cache: READING_NO_STORE },
    FullStorySchema,
  );
}

export function getLatestStories() {
  return request<StoryCard[]>(
    "/stories/homepage/latest",
    { next: HOMEPAGE_REVALIDATE },
    z.array(StoryCardSchema),
  );
}

export function getMostLikedStories() {
  return request<StoryCard[]>(
    "/stories/homepage/most-liked",
    { next: HOMEPAGE_REVALIDATE },
    z.array(StoryCardSchema),
  );
}

export function getMostReadStories() {
  return request<StoryCard[]>(
    "/stories/homepage/most-read",
    { next: HOMEPAGE_REVALIDATE },
    z.array(StoryCardSchema),
  );
}

export function getAuthorsChoiceStories() {
  return request<StoryCard[]>(
    "/stories/homepage/authors-choice",
    { next: HOMEPAGE_REVALIDATE },
    z.array(StoryCardSchema),
  );
}

// ── Series ───────────────────────────────────────────────────────

export interface SeriesListQuery extends StoryListQuery {}

export function getSeriesList(query: SeriesListQuery = {}) {
  const params = new URLSearchParams();
  if (query.search) params.set("search", query.search);
  if (query.tagIds) for (const id of query.tagIds) params.append("tagIds", id);
  if (query.page) params.set("page", String(query.page));
  if (query.limit) params.set("limit", String(query.limit));
  const qs = params.toString() ? `?${params}` : "";
