import { NextResponse, type NextRequest } from "next/server";

// Must match the value the backend uses when issuing the cookie —
// see backend/src/auth/strategies/jwt.strategy.ts#ADMIN_SESSION_COOKIE.
// Different process, different env, so the name has to be hard-coded
// in both places.
const ADMIN_SESSION_COOKIE = "lucifer_admin_session";

/**
 * Site-wide proxy (Next.js 16 — the renamed-from-middleware file).
 * Two responsibilities:
 *
 * 1) Admin gate (audit H-02). Blocks /admin routes when the admin
 *    session cookie is absent; bounces /admin/login back to /admin
 *    when the cookie IS present. Cookie verification is
 *    presence-only here — the backend's JwtStrategy does the
 *    cryptographic verify per API call, and adminApi.ts redirects
 *    to /admin/login on the resulting 401.
 *
 * 2) CSP nonce + enforce (audit C-04 phase 2). Generates a fresh
 *    nonce per request, threads it into the
 *    `Content-Security-Policy` header (now ENFORCING, no longer
 *    report-only) and into a custom `x-nonce` request header so
 *    server components can read it (the JsonLd component does, to
 *    attach `nonce={nonce}` on its inline script tag). Next.js
 *    framework code auto-applies the same nonce to its own
 *    bundled / framework / hydration scripts.
 *
 * Trade-off: pages that read the nonce — i.e. anything rendering
 * JsonLd through the root layout, which is every page — become
 * dynamic. For this site's traffic profile that's acceptable; the
 * alternative is `'unsafe-inline'` in `script-src` forever.
 */
export function proxy(request: NextRequest) {
  // ── /admin gate ────────────────────────────────────────────────
  const { pathname } = request.nextUrl;
  const hasCookie = !!request.cookies.get(ADMIN_SESSION_COOKIE)?.value;

  if (pathname === "/admin/login") {
    if (hasCookie) {
      const url = request.nextUrl.clone();
      url.pathname = "/admin/stories";
      return NextResponse.redirect(url);
    }
  } else if (pathname === "/admin" || pathname.startsWith("/admin/")) {
    if (!hasCookie) {
      const url = request.nextUrl.clone();
      url.pathname = "/admin/login";
      url.searchParams.set("next", pathname);
      return NextResponse.redirect(url);
    }
  }

  // ── CSP nonce ──────────────────────────────────────────────────
  //
  // Per-request nonce. The Web-Crypto random UUID base64-encoded
  // gives ~128 bits of entropy in a ~24-char string — fine for CSP
  // nonce purposes. btoa on the UUID directly (with dashes) yields
  // a valid CSP nonce token.
  const nonce = btoa(crypto.randomUUID());
  const isDev = process.env.NODE_ENV === "development";

  // - 'strict-dynamic' delegates trust from the nonce'd entry script
  //   to any scripts it loads (Next.js's runtime + chunks). With
  //   strict-dynamic, the host allowlist in script-src is ignored
  //   by modern browsers — only nonces / hashes matter. Older
  //   browsers fall back to the host allowlist ('self').
  // - 'unsafe-eval' only in dev: React's enhanced error stacks use
  //   eval(). Production builds don't.
  // - style-src keeps 'unsafe-inline' because the codebase uses
  //   `style={{...}}` props extensively (admin error boundary, etc.),
  //   which compile to inline `style=` attributes that are subject
  //   to CSP style-src. Adding nonces to every JSX style prop would
  //   be a deep refactor for marginal benefit — style-src XSS is a
  //   rare and limited-impact vector.
  // - connect-src includes the API origin so fetch() from the
  //   frontend can reach the backend.
  // - frame-ancestors 'none' duplicates X-Frame-Options: SAMEORIGIN
  //   but is the CSP3 way; both can coexist.
  const csp = [
    "default-src 'self'",
    `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'${
      isDev ? " 'unsafe-eval'" : ""
    }`,
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' data: blob:",
    "font-src 'self' data:",
    "connect-src 'self' https://lucifersdiary.com",
    "frame-ancestors 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "object-src 'none'",
    "upgrade-insecure-requests",
  ].join("; ");

  const requestHeaders = new Headers(request.headers);
  requestHeaders.set("x-nonce", nonce);
  // Setting on the REQUEST headers lets Next.js's nonce-extraction
  // see it during render. Setting on the RESPONSE headers (below)
  // is what the browser actually enforces.
  requestHeaders.set("Content-Security-Policy", csp);

  const response = NextResponse.next({
    request: { headers: requestHeaders },
  });
  response.headers.set("Content-Security-Policy", csp);
  return response;
}

