import {
  ConflictException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { slugify } from '../common/utils/slug';
import { PrismaService } from '../prisma/prisma.service';
import { CreateTagDto } from './dto/create-tag.dto';
import { UpdateTagDto } from './dto/update-tag.dto';

@Injectable()
export class TagsService {
  constructor(private readonly prisma: PrismaService) {}

  findAll() {
    return this.prisma.tag.findMany({ orderBy: { name: 'asc' } });
  }

  /**
   * Public tag list: only tags attached to at least one published piece.
   * Hides the long tail of seeded-but-unused tags from the homepage
   * filter bar. Admin still uses findAll() to manage every tag.
   */
  findAllUsed() {
    return this.prisma.tag.findMany({
      where: {
        OR: [
          { storyTags: { some: { story: { publishedAt: { not: null } } } } },
          {
            chapterTags: {
              some: { chapter: { publishedAt: { not: null } } },
            },
          },
          {
            seriesTags: {
              some: {
                series: {
                  chapters: { some: { publishedAt: { not: null } } },
                },
              },
            },
          },
        ],
      },
      orderBy: { name: 'asc' },
    });
  }

  async findOne(id: string) {
    const tag = await this.prisma.tag.findUnique({ where: { id } });
    if (!tag) throw new NotFoundException(`Tag ${id} not found`);
    return tag;
  }

  async findOneBySlug(slug: string) {
    const tag = await this.prisma.tag.findUnique({ where: { slug } });
    if (!tag) throw new NotFoundException(`Tag ${slug} not found`);
    return tag;
  }

  async create(dto: CreateTagDto) {
    const name = normalize(dto.name);
    try {
      return await this.prisma.tag.create({
        data: {
          name,
          slug: await this.uniqueSlugFor(name),
          isAdult: dto.isAdult ?? false,
        },
      });
    } catch (e) {
      throw remapUniqueViolation(e, name);
    }
  }

  async update(id: string, dto: UpdateTagDto) {
    const existing = await this.findOne(id);
    const name = dto.name !== undefined ? normalize(dto.name) : undefined;
    const slug =
      name !== undefined && name !== existing.name
        ? await this.uniqueSlugFor(name, id)
        : undefined;
    try {
      return await this.prisma.tag.update({
        where: { id },
        data: {
          ...(name !== undefined && { name }),
          ...(slug !== undefined && { slug }),
          ...(dto.isAdult !== undefined && { isAdult: dto.isAdult }),
        },
      });
    } catch (e) {
      throw remapUniqueViolation(e, name ?? '');
    }
  }

  private async uniqueSlugFor(
    name: string,
    excludeId?: string,
  ): Promise<string> {
    const base = slugify(name) || 'tag';
    let candidate = base;
    let n = 2;
    // Append -2, -3, ... until we hit an unused slug. The migration's
    // backfill uses the same convention, so collisions only happen for
    // case-only duplicates of existing names.
    while (true) {
      const conflict = await this.prisma.tag.findFirst({
        where: { slug: candidate, ...(excludeId && { NOT: { id: excludeId } }) },
        select: { id: true },
      });
      if (!conflict) return candidate;
      candidate = `${base}-${n}`;
      n += 1;
    }
  }

  async remove(id: string) {
    await this.findOne(id);
    await this.prisma.tag.delete({ where: { id } });
    return { message: 'Tag deleted' };
  }
}

function normalize(name: string): string {
  return name.trim().toLowerCase();
}

function remapUniqueViolation(e: unknown, name: string): unknown {
  if (
    e instanceof Prisma.PrismaClientKnownRequestError &&
    e.code === 'P2002'
  ) {
    return new ConflictException(`A tag named "${name}" already exists`);
  }
  return e;
}

