  title: {
    default: SITE_NAME,
    template: `%s — ${SITE_NAME}`,
  },
  description: SITE_DESCRIPTION,
  applicationName: SITE_NAME,
  authors: [{ name: SITE_AUTHOR.name, url: SITE_AUTHOR.url }],
  creator: SITE_AUTHOR.name,
  publisher: SITE_NAME,
  alternates: {
    canonical: "/",
    types: {
      "application/atom+xml": [{ url: "/feed.xml", title: SITE_NAME }],
    },
  },
  openGraph: {
    type: "website",
    siteName: SITE_NAME,
    title: SITE_NAME,
    description: SITE_DESCRIPTION,
    url: SITE_URL,
    // The default image is generated by app/opengraph-image.tsx and
    // resolved automatically by Next.js — per-page metadata can
    // override it without redefining the rest of this block.
  },
  twitter: {
    card: "summary_large_image",
    title: SITE_NAME,
    description: SITE_DESCRIPTION,
  },
  robots: {
    index: true,
    follow: true,
  },
  // Self-label as adult content so search engines / filters classify
  // the site correctly instead of flagging it. Renders
  // <meta name="rating" content="adult"> site-wide.
  other: {
    rating: "adult",
  },
};

// themeColor / colorScheme moved out of `metadata` and into a separate
// `viewport` export in Next.js 14+ — the old location is deprecated.
// The hex matches the resting --bg token in globals.css so the mobile
// browser chrome blends into the page rather than flashing a lighter
// default.
export const viewport: Viewport = {
  themeColor: "#0a0a0a",
  colorScheme: "dark",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    // suppressHydrationWarning on <html> covers the data-theme attribute the
    // boot script sets before React hydrates; suppressing on <body> handles
    // the Grammarly extension's own attribute injection.
    <html
      lang="en"
      className="dark h-full antialiased"
      data-theme="dark"
      suppressHydrationWarning
    >
      <body className="min-h-full flex flex-col" suppressHydrationWarning>
        {/*
          Boot script — applies the persisted theme + reading prefs to
          <html> before React hydrates so returning visitors don't see
          a flash of the default theme. Lives as a static file under
          /public/boot.js so React 19 doesn't flag a <script> tag
          inside the component tree (an inline child trips
          "Encountered a script tag while rendering React component"
          even when wrapped in next/script).
        */}
        {/* Skip-to-content link — first focusable element in the
            DOM so keyboard / screen-reader users can bypass the
            site header. Targets the page's `<main id="main">`
            which every route renders. The element is visually
            parked off-screen via `.skip-link` in globals.css and
            slides into the top-left when focused. */}
        <a href="#main" className="skip-link">
          Skip to content
        </a>
        <Script
          id="lucifer-boot-prefs"
          src="/boot.js"
          strategy="beforeInteractive"
        />
        <JsonLd
          data={{
            "@context": "https://schema.org",
            "@type": "WebSite",
            name: SITE_NAME,
            description: SITE_DESCRIPTION,
            url: SITE_URL,
            author: {
              "@type": "Person",
              name: SITE_AUTHOR.name,
              url: SITE_AUTHOR.url,
            },
            publisher: {
              "@type": "Organization",
              name: SITE_NAME,
              url: SITE_URL,
            },
          }}
        />
        {children}
        <PublicGates />
      </body>
    </html>
  );
}

