export async function generateMetadata({
  params,
}: {
  params: Promise<{ id: string }>;
}): Promise<Metadata> {
  const { id } = await params;
  try {
    const story = await getStory(id);
    const description = stripHtml(story.excerpt);
    const url = `/story/${story.id}`;
    return {
      title: story.title,
      description,
      // Without an explicit canonical, querystring variants (e.g.
      // /story/abc?page=2) would all be eligible for indexing. Pin it
